@section('content')<div class="admin-heading"><h1>Limbi</h1><p>O limba noua ramane inactiva pana la livrarea traducerilor si rutelor prin deploy. Adminul ramane intotdeauna in romana.</p></div><section class="library-panel admin-panel"><h2>Adauga limba</h2><form class="auth-form admin-form-grid" method="POST" action="{{ route('admin.languages.store') }}">@csrf<label>Cod limba<input name="locale" maxlength="5" pattern="[a-z]{2}(-[a-z]{2})?" required></label><label>Nume afisat<input name="display_name" maxlength="80" required></label><label>Nume nativ<input name="native_name" maxlength="80" required></label><label>Moneda<select name="default_currency">@foreach(['RON','EUR','HUF','BGN','USD','GBP','CHF'] as $code)<option>{{ $code }}</option>@endforeach</select></label><button class="library-small-button" type="submit">Creeaza inactiva</button></form></section><div class="admin-record-list">@foreach($languages as $language)<section class="library-panel admin-panel"><div class="admin-record-heading"><h2>{{ $language->native_name }} · {{ strtoupper($language->locale) }}</h2><span>{{ $language->is_default ? 'Implicita' : ($language->is_active ? 'Activa' : 'Inactiva') }}</span></div><form class="auth-form admin-form-grid" method="POST" action="{{ route('admin.languages.update',['language'=>$language->id]) }}">@csrf @method('PATCH')<label>Nume afisat<input name="display_name" value="{{ $language->display_name }}" required maxlength="80"></label><label>Nume nativ<input name="native_name" value="{{ $language->native_name }}" required maxlength="80"></label><label>Moneda<select name="default_currency">@foreach(['RON','EUR','HUF','BGN','USD','GBP','CHF'] as $code)<option @selected($language->default_currency === $code)>{{ $code }}</option>@endforeach</select></label><div class="admin-checks"><input type="hidden" name="is_active" value="0"><label class="admin-checkbox"><input type="checkbox" name="is_active" value="1" @checked($language->is_active)>Activa</label><input type="hidden" name="translation_ready" value="0"><label class="admin-checkbox"><input type="checkbox" name="translation_ready" value="1" @checked($language->translation_ready)>Traduceri si rute pregatite</label></div><button class="library-small-button" type="submit">Salveaza</button></form>@unless($language->is_default)<form method="POST" action="{{ route('admin.languages.default',['language'=>$language->id]) }}" class="admin-secondary-action">@csrf<button class="library-small-button" type="submit">Seteaza ca implicita</button></form>@endunless @if(!$language->is_active && !array_key_exists($language->locale,config('vault.locales')))<details class="admin-delete"><summary>Sterge limba</summary><form method="POST" action="{{ route('admin.languages.destroy',['language'=>$language->id]) }}">@csrf @method('DELETE')<label class="admin-checkbox"><input type="checkbox" name="confirm" value="1" required>Confirm stergerea limbii inactive.</label><button class="danger-button" type="submit">Sterge</button></form></details>@endif</section>@endforeach</div>@endsection
